import heapq
from collections import Counter


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    order = names if name_order == "ascending" else list(reversed(names))
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        if name in roots:
            low, high = roots[name]
            versions = [v for v in versions if low <= v <= high]
            domains.append(versions)
        else:
            domains.append([-1] + versions)

    best_vector = None
    best_versions = None
    for values in product(*domains):
        chosen = dict(zip(names, values))
        rows = {}
        for name, version in chosen.items():
            if version != -1:
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)

        edges = {name: [] for name in rows}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = chosen.get(target, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in rows:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(rows):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in rows):
            continue
        vector = tuple(chosen[name] for name in order)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best_versions = {name: version for name, version in chosen.items()
                             if version != -1}
    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def ledger(data):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = Counter(job["group"] for job in chosen)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        for _, delta in sorted(events, key=lambda item: (item[0], item[1])):
            active += delta
            if active > 2:
                break
        else:
            value = sum(job["value"] for job in chosen)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start = data["start"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                nxt = (next_node, next_mask, left)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


